398	<body>
399	  <main>
400	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-describedby="hint-text">
401	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
402	        <circle cx="200" cy="200" r="200"/>
403	      </svg>
404	    </button>
405	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
406	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
407	    <div class="controls" role="group" aria-label="Circle controls">
408	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
409	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
410	    </div>
411	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
412	  </main>
413	
414	  <script defer>
415	    (() => {
416	      const CONFIG = {
417	        storageKey: 'circle-state',
418	        tapDelay: 300,
419	        colorShiftDuration: 500,
420	        saveDebounceDuration: 100,
421	        colorModes: [
422	          { class: 'default', name: 'Default White' },
423	          { class: 'color-mode-1', name: 'Pink' },
424	          { class: 'color-mode-2', name: 'Teal' },
425	          { class: 'color-mode-3', name: 'Mint' },
426	          { class: 'color-mode-4', name: 'Purple' },
427	          { class: 'color-mode-5', name: 'Orange' }
428	        ],
429	        isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0
430	      };
431	
432	      const el = {
433	        circle: document.getElementById('decorative-circle'),
434	        hint: document.getElementById('hint-text'),
435	        modeIndicator: document.getElementById('mode-indicator'),
436	        cycleBtn: document.getElementById('cycle-btn'),
437	        resetBtn: document.getElementById('reset-btn')
438	      };
439	
440	      let state = { active: false, colorMode: 0 };
441	      let tapCount = 0;
442	      let tapTimeout = null;
443	      let animatingColorShift = false;
444	      let saveTimeout = null;
445	
446	      const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
447	      const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
448	
449	      const storage = {
450	        save() {
451	          clearTimeout(saveTimeout);
452	          saveTimeout = setTimeout(() => {
453	            try {
454	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
455	            } catch (e) {
456	              if (e.name === 'QuotaExceededError') {
457	                console.warn('localStorage full, state not saved');
458	              }
459	            }
460	          }, CONFIG.saveDebounceDuration);
461	        },
462	        load() {
463	          try {
464	            const saved = localStorage.getItem(CONFIG.storageKey);
465	            if (saved) {
466	              const parsed = JSON.parse(saved);
467	              if (parsed && typeof parsed === 'object' && 'active' in parsed && 'colorMode' in parsed) {
468	                state = parsed;
469	              }
470	            }
471	          } catch (e) {
472	            // Silent failure - use default state
473	          }
474	        }
475	      };
476	
477	      const updateClasses = () => {
478	        const colorClasses = CONFIG.colorModes.map(m => m.class);
479	        el.circle.classList.remove('active', ...colorClasses);
480	        el.circle.setAttribute('aria-pressed', state.active);
481	        if (state.active) el.circle.classList.add('active');
482	        if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
483	      };
484	
485	      const getHintText = () => {
486	        if (CONFIG.isTouch) {
487	          return state.active ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle';
488	        }
489	        return state.active ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle';
490	      };
491	
492	      const updateUI = () => {
493	        el.hint.textContent = getHintText();
494	
495	        const showMode = state.active && state.colorMode > 0;
496	        el.modeIndicator.classList.toggle('visible', showMode);
497	        if (showMode) {
498	          const modeName = getColorModeName(state.colorMode);
499	          el.modeIndicator.textContent = `◆ ${modeName.toUpperCase()}`;
500	        }
501	      };
502	
503	      const applyState = () => {
504	        updateClasses();
505	        updateUI();
506	      };
507	
508	      const toggleActive = () => {
509	        state.active = !state.active;
510	        applyState();
511	        storage.save();
512	      };
513	
514	      const cycleColor = () => {
515	        if (animatingColorShift) return;
516	        animatingColorShift = true;
517	        state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
518	        state.active = true;
519	        el.circle.classList.add('color-shifting');
520	        setTimeout(() => {
521	          el.circle.classList.remove('color-shifting');
522	          animatingColorShift = false;
523	        }, CONFIG.colorShiftDuration);
524	        applyState();
525	        storage.save();
526	      };
527	
528	      const resetState = () => {
529	        state = { active: false, colorMode: 0 };
530	        applyState();
531	        storage.save();
532	      };
533	
534	      const handleClick = () => {
535	        if (!CONFIG.isTouch) toggleActive();
536	      };
537	
538	      const handleDblClick = () => {
539	        cycleColor();
540	      };
541	
542	      const handleTouchEnd = () => {
543	        tapCount++;
544	        clearTimeout(tapTimeout);
545	        if (tapCount === 1) {
546	          tapTimeout = setTimeout(() => {
547	            if (tapCount === 1) toggleActive();
548	            tapCount = 0;
549	          }, CONFIG.tapDelay);
550	        } else if (tapCount === 2) {
551	          cycleColor();
552	          tapCount = 0;
553	        }
554	      };
555	
556	      const keyHandlers = {
557	        ' ': toggleActive,
558	        'enter': toggleActive,
559	        'escape': resetState,
560	        'c': cycleColor,
561	        'r': resetState
562	      };
563	
564	      const handleKeyDown = (e) => {
565	        const key = e.key.toLowerCase();
566	        const handler = keyHandlers[key];
567	        if (handler) {
568	          e.preventDefault();
569	          handler();
570	        }
571	      };
572	
573	      const initListeners = () => {
574	        if (CONFIG.isTouch) {
575	          el.circle.addEventListener('touchend', handleTouchEnd, { passive: true });
576	        } else {
577	          el.circle.addEventListener('click', handleClick, { passive: true });
578	          el.circle.addEventListener('dblclick', handleDblClick, { passive: true });
579	        }
580	        el.circle.addEventListener('blur', () => {
581	          tapCount = 0;
582	          clearTimeout(tapTimeout);
583	        });
584	        document.addEventListener('keydown', handleKeyDown);
585	        el.cycleBtn.addEventListener('click', cycleColor, { passive: true });
586	        el.resetBtn.addEventListener('click', resetState, { passive: true });
587	      };
588	
589	      const initApp = () => {
590	        storage.load();
591	        applyState();
592	        initListeners();
593	        el.circle.focus();
594	      };
595	
596	      const ensureSave = () => {
597	        clearTimeout(saveTimeout);
598	        try {
599	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
600	        } catch (e) {
601	          if (e.name !== 'QuotaExceededError') console.warn(e);
602	        }
603	      };
